// Build-time only: the shim imports the generated bytes, never Track's handlers.
import fs from 'node:fs';
import { H2A_CLI_MCP_TOOL_DESCRIPTORS } from '../packages/h2a/dist/runtime/mcp/tools.js';
const path = 'packages/h2a/src/runtime/mcp-central-descriptor.js';
const bytes = '// Generated by scripts/generate-mcp-descriptor.mjs from the server definitions.\n' +
  'export const embeddedTools = ' + JSON.stringify(H2A_CLI_MCP_TOOL_DESCRIPTORS, null, 2) + ';\n' +
  'export const embeddedPackageVersion = ' + JSON.stringify(JSON.parse(fs.readFileSync('packages/h2a/package.json')).version) + ';\n';
if (process.argv.includes('--check')) {
  if (fs.readFileSync(path, 'utf8') !== bytes) throw new Error('embedded_descriptor_stale: run node scripts/generate-mcp-descriptor.mjs and rebuild');
} else fs.writeFileSync(path, bytes);
